create extension if not exists pgcrypto;
create type public.route_status as enum ('draft','scanning','ready','optimized','in_progress','completed','cancelled');
create type public.package_status as enum ('scanned','address_pending','ready','out_for_delivery','delivered','failed');
create type public.stop_status as enum ('pending','skipped','completed','failed');
create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, name text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.routes (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id), name text not null, route_date date not null, status public.route_status not null default 'draft', origin_address text not null, origin_lat double precision, origin_lng double precision, destination_address text, destination_lat double precision, destination_lng double precision, return_to_origin boolean not null default false, optimizer_provider text, estimated_distance_meters integer check(estimated_distance_meters >= 0), estimated_duration_seconds integer check(estimated_duration_seconds >= 0), actual_distance_meters integer check(actual_distance_meters >= 0), started_at timestamptz, completed_at timestamptz, archived_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create unique index one_active_route_per_user on public.routes(user_id) where status = 'in_progress'; create index routes_user_date_idx on public.routes(user_id, route_date desc);
create table public.route_stops (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id), route_id uuid not null references public.routes(id) on delete cascade, sequence integer not null check(sequence > 0), address_full text not null, latitude double precision not null, longitude double precision not null, status public.stop_status not null default 'pending', estimated_arrival timestamptz, actual_arrival timestamptz, distance_from_previous_meters integer check(distance_from_previous_meters >= 0), duration_from_previous_seconds integer check(duration_from_previous_seconds >= 0), completed_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(route_id, sequence));
create table public.packages (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id), route_id uuid not null references public.routes(id) on delete cascade, stop_id uuid references public.route_stops(id) on delete set null, tracking_code text not null, barcode_raw text, barcode_format text, recipient_name text, recipient_phone text, address_full text, street text, number text, complement text, neighborhood text, city text, state text, postal_code text, latitude double precision, longitude double precision, status public.package_status not null default 'scanned', failure_reason text, notes text, vehicle_position text, scanned_at timestamptz not null default now(), delivered_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(route_id, tracking_code));
create index packages_route_status_idx on public.packages(route_id, status); create index packages_stop_idx on public.packages(stop_id);
create table public.saved_locations (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id), label text not null, address_full text not null, latitude double precision not null, longitude double precision not null, created_at timestamptz not null default now(), unique(user_id,label));
create table public.route_events (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id), route_id uuid not null references public.routes(id) on delete cascade, package_id uuid references public.packages(id) on delete set null, stop_id uuid references public.route_stops(id) on delete set null, event_type text not null, idempotency_key text unique, metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now());
alter table public.profiles enable row level security; alter table public.routes enable row level security; alter table public.route_stops enable row level security; alter table public.packages enable row level security; alter table public.saved_locations enable row level security; alter table public.route_events enable row level security;
create policy profiles_own on public.profiles for all using(id=auth.uid()) with check(id=auth.uid()); create policy routes_own on public.routes for all using(user_id=auth.uid()) with check(user_id=auth.uid()); create policy stops_own on public.route_stops for all using(user_id=auth.uid()) with check(user_id=auth.uid()); create policy packages_own on public.packages for all using(user_id=auth.uid()) with check(user_id=auth.uid()); create policy saved_locations_own on public.saved_locations for all using(user_id=auth.uid()) with check(user_id=auth.uid()); create policy route_events_own on public.route_events for all using(user_id=auth.uid()) with check(user_id=auth.uid());
